Time complexity: `O((rows * cols)^2)` in the worst case because the grid may be scanned once per minute.

Space complexity: `O(rows * cols)` for the list of rotten positions. The input grid is modified.

I used a queue that starts with every rotten orange. All cells already in the queue belong to the same minute, so I save the queue size before processing a layer. Newly rotten cells wait for the next layer.

The fresh count avoids scanning the grid again after every minute. The grid is changed in place, so a fresh orange changing from `1` to `2` also works as the visited mark.

For example, with `[[2,1,1],[0,1,1]]`, the first layer rots the orange at `(0,1)`. The next layer continues from there and reaches the remaining oranges.

```cpp
class Solution{
public:
    int orangesRotting(vector<vector<int>> &grid) {
        if (grid.empty() || grid[0].empty()) {
            return 0;
        }

        int rows = grid.size();
        int cols = grid[0].size();
        queue<pair<int, int>> rotten;
        int fresh = 0;

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == 2) {
                    rotten.push({r, c});
                } else if (grid[r][c] == 1) {
                    ++fresh;
                }
            }
        }

        if (fresh == 0) {
            return 0;
        }

        int minutes = 0;
        int directions[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!rotten.empty() && fresh > 0) {
            int levelSize = rotten.size();
            ++minutes;

            while (levelSize-- > 0) {
                auto current = rotten.front();
                rotten.pop();

                for (auto &direction : directions) {
                    int nextRow = current.first + direction[0];
                    int nextCol = current.second + direction[1];

                    if (nextRow < 0 || nextRow >= rows ||
                        nextCol < 0 || nextCol >= cols) {
                        continue;
                    }

                    if (grid[nextRow][nextCol] != 1) {
                        continue;
                    }

                    grid[nextRow][nextCol] = 2;
                    --fresh;
                    rotten.push({nextRow, nextCol});
                }
            }
        }

        return fresh == 0 ? minutes : -1;
    }
};
```

